import pandas as pd
from pymatgen.core import Structure
from pymatgen.analysis.structure_matcher import StructureMatcher
P=pd.read_csv('nlo_pool.csv');ss={r.candidate_id:Structure.from_str(r.poscar,fmt='poscar') for _,r in P.iterrows()}
sm=StructureMatcher(primitive_cell=True,attempt_supercell=True)
for a in ['c050','c051','c052']:
 for b in ['c050','c051','c052']:
  print(a,b,sm.fit(ss[a],ss[b]),sm.get_rms_dist(ss[a],ss[b]))
